size_t virtio_pci_modern_db_size(void) {
    return sizeof(g_db) / sizeof(g_db[0]);
}

void virtio_pci_modern_init(void) {
    g_ready = true;
    kprintf("[DRV/VIRTIO-1.2] VirtIO 1.2 PCI Modern Packed Virtqueues + VBoxGuest HGCM Integration (%lu rules)\n", (unsigned long)virtio_pci_modern_db_size());
}

bool virtio_pci_modern_selftest(void) {
    return g_ready && virtio_pci_modern_db_size() >= 3520;
}
